mapper.delete:
DELETE FROM tb_eval_item
WHERE review_master_code = #{reviewMasterCode}
  AND company_code = #{companyCode}

mapper.select:
SELECT m.company_code, m.review_master_code, m.reivew_master_name, m.review_start_date, m.review_end_date,
NVL(tm.total_member_cnt, 0) AS total_member_cnt, NVL(SUM(CASE WHEN r.review_status = '2' THEN 1 ELSE 0 END), 0) AS completed_cnt,
CASE WHEN NVL(COUNT(r.review_code), 0) = 0 THEN '미평가' WHEN NVL(SUM(CASE WHEN r.review_status = '2' THEN 1 ELSE 0 END), 0) < NVL(tm.total_member_cnt, 0) THEN '진행중' ELSE '완료' END AS review_status FROM tb_hr_review_master m
LEFT JOIN tb_hr_review r ON r.company_code = m.company_code AND r.review_master_code = m.review_master_code AND r.rater_user_id = #{raterUserId}
LEFT JOIN ( SELECT leader.company_code, leader.user_id AS rater_user_id, COUNT(member.USER_ID) AS total_member_cnt FROM tb_user_master leader JOIN tb_user_master member ON member.company_code = leader.company_code AND member.dept = leader.dept AND member.user_id <> leader.user_id GROUP BY leader.company_code, leader.user_id ) tm ON tm.company_code = m.company_code AND tm.rater_user_id = #{raterUserId}
WHERE m.company_code = #{companyCode} AND m.use_yn = 'Y' GROUP BY m.company_code, m.review_master_code, m.Review_master_name, m.review_start_date, m.review_end_date, tm.total_member_cnt ORDER BY m.review_start_date DESC
